const iceLancerSheet=new Image();iceLancerSheet.assetSrc='assets/ice-lancer-v1.png';
function beginIceLancer(e){let mode=dist(e,p)<=130?'sweep':'thrust',angle=Math.atan2(p.y-e.y,p.x-e.x),origin={x:e.x,y:e.y},reach=0;if(mode==='thrust')for(let r=10;r<=360;r+=10){if(!lineClear(origin,{x:e.x+Math.cos(angle)*r,y:e.y+Math.sin(angle)*r}))break;reach=r;}e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'iceLancerStance',bespoke:true,mode,angle,origin,reach,windup:mode==='sweep'?.95:1.25,fired:false};}
function iceLancerContains(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,c=Math.cos(a.angle),s=Math.sin(a.angle);if(a.mode==='thrust'){let along=dx*c+dy*s,side=-dx*s+dy*c;return along>=60-1e-8&&along<=a.reach+1e-8&&Math.abs(side)<=20+1e-8;}let delta=Math.atan2(dy,dx)-a.angle;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return Math.hypot(dx,dy)<=155+1e-8&&Math.abs(delta)<=Math.PI*4/9+1e-8;}
const iceLancerAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e3')return iceLancerAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='iceLancerStance'){
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=330&&clear){beginIceLancer(e);return;}e.state='idle';if(d>800&&!e.aware||d<=200)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,86*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,17)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.4;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=a.windup){a.fired=true;e.struck=true;if(iceLancerContains(a,p)&&lineClear(a.origin,p))hurt(a.mode==='sweep'?48:76);burst(e.x+Math.cos(a.angle)*(a.mode==='sweep'?70:130),e.y+Math.sin(a.angle)*(a.mode==='sweep'?70:130),45,'#b1e4f4');playSound('slash',e.x,e.y);}
 if(e.elapsed>=a.windup+.8){e.attack=null;e.state='idle';e.t=2.2;}
};
const iceLancerDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r5e3'||!iceLancerSheet.complete||!iceLancerSheet.naturalWidth||!iceLancerSheet.naturalHeight)return iceLancerDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:0,col:0};else if(e.attack?.pattern==='iceLancerStance')f={row:2,col:(e.attack.mode==='sweep'?2:0)+(e.attack.fired?1:0)};let q=project(e.x,e.y),sw=iceLancerSheet.naturalWidth/4,sh=iceLancerSheet.naturalHeight/3,w=240,h=w*sh/sw,anchor=[.88,.87,.86][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,iceLancerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(iceLancerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;
};
const iceLancerSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e3'?145:iceLancerSizeBase(e);
const iceLancerGroundBase=drawGroundEffects;drawGroundEffects=()=>{iceLancerGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e3'):enemies)){let a=e.attack;if(e.species!=='r5e3'||e.hp<=0||a?.pattern!=='iceLancerStance'||e.elapsed>=a.windup+.2||!visibleAt(e.x,e.y))continue;ctx.save();ctx.strokeStyle=a.fired?'#ecfbff':a.mode==='sweep'?'#dda1eb':'#83d9ed';ctx.fillStyle=a.mode==='sweep'?'#be7cdb24':'#6bbdc724';ctx.lineWidth=a.fired?3:2;ctx.beginPath();if(a.mode==='sweep'){let q=project(a.origin.x,a.origin.y);ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.moveTo(0,0);ctx.arc(0,0,155,a.angle-Math.PI*4/9,a.angle+Math.PI*4/9);ctx.closePath();}else{if(a.reach<60){ctx.restore();continue;}let c=Math.cos(a.angle),s=Math.sin(a.angle);for(let [i,[along,side]]of [[60,-20],[a.reach,-20],[a.reach,20],[60,20]].entries()){let q=project(a.origin.x+c*along-s*side,a.origin.y+s*along+c*side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();}ctx.fill();ctx.stroke();ctx.restore();}};
